public static String convertDatesToWeekdays(String date) {
    try {
        String[] dateParts = date.split(" ");
        if (dateParts.length != 3) {
            throw new IllegalArgumentException("Date format must be 'MM dd yyyy'");
        }

        int month = Integer.parseInt(dateParts[0]);
        int day = Integer.parseInt(dateParts[1]);
        int year = Integer.parseInt(dateParts[2]);

        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month must be between 1 and 12");
        }
        if (day < 1 || day > 31) {
            throw new IllegalArgumentException("Day must be between 1 and 31");
        }

        String[] months = {"January", "February", "March", "April", "May", "June",
                            "July", "August", "September", "October", "November", "December"};
        String monthName = months[month - 1];

        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.set(year, month - 1, day);
        int dayOfWeek = calendar.get(java.util.Calendar.DAY_OF_WEEK);

        String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
        String weekdayName = weekdays[dayOfWeek - 1];

        return monthName + " " + day + ", " + year + " is a " + weekdayName;
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Date components must be numeric", e);
    }
}

